-- Adding the transactional subscriptions
use [CustDB]
exec sp_addsubscription @publication = N'CustDB_DBTrans_CustInfo', @subscriber = N'DBGRP01L', @destination_db = N'CustDB', @subscription_type = N'Push', @sync_type = N'replication support only', @article = N'all', @update_mode = N'read only', @subscriber_type = 0
exec sp_addpushsubscription_agent @publication = N'CustDB_DBTrans_CustInfo', @subscriber = N'DBGRP01L', @subscriber_db = N'CustDB', @job_login = null, @job_password = null, @subscriber_security_mode = 1, @frequency_type = 64, @frequency_interval = 1, @frequency_relative_interval = 1, @frequency_recurrence_factor = 0, @frequency_subday = 4, @frequency_subday_interval = 5, @active_start_time_of_day = 0, @active_end_time_of_day = 235959, @active_start_date = 0, @active_end_date = 0, @dts_package_location = N'Distributor'
GO
